import{_ as i,C as r,o as d,c as l,j as e,a as s,E as a,a2 as n}from"./chunks/framework.D0xy3_1I.js";const B=JSON.parse('{"title":"3. Rules & mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/rules.md","filePath":"gdd/rules.md"}'),h={name:"gdd/rules.md"},p={id:"_3-1-win-lose-limits",tabindex:"-1"},u={id:"_3-2-fish",tabindex:"-1"},g={id:"_3-3-obstacles-tapping-one-counts-as-a-wrong-tap",tabindex:"-1"},f={id:"_3-4-boosters",tabindex:"-1"},m={id:"_3-5-random-events",tabindex:"-1"},b={id:"_3-6-pump-tube-from-l16",tabindex:"-1"},w={id:"_3-7-bounty-tanks-from-l25",tabindex:"-1"},c={id:"_3-8-collision-and-layout",tabindex:"-1"},k={id:"_3-9-tutorial-and-introductions",tabindex:"-1"},y={id:"_3-10-themes-and-tank-shapes",tabindex:"-1"},v={id:"_3-11-coins-boosters-and-ads",tabindex:"-1"},L={id:"_3-12-the-win-sequence",tabindex:"-1"};function T(A,t,_,x,P,S){const o=r("Badge");return d(),l("div",null,[t[36]||(t[36]=e("h1",{id:"_3-rules-mechanics",tabindex:"-1"},[s("3. Rules & mechanics "),e("a",{class:"header-anchor",href:"#_3-rules-mechanics","aria-label":'Permalink to "3. Rules & mechanics"'},"​")],-1)),t[37]||(t[37]=e("p",null,[s("Every number below was checked against the code on 18 Nov 2026 ("),e("code",null,"game/src/main.js"),s(", "),e("code",null,"game/src/levelcfg.js"),s(", "),e("code",null,"game/src/levels.json"),s("). The per-level values are in "),e("a",{href:"./levels"},"Levels"),s(".")],-1)),e("h2",p,[t[0]||(t[0]=s("3.1 Win, lose, limits ",-1)),a(o,{type:"tip",text:"Live"}),t[1]||(t[1]=s()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#_3-1-win-lose-limits","aria-label":'Permalink to "3.1 Win, lose, limits <Badge type="tip" text="Live" />"'},"​",-1))]),t[38]||(t[38]=n('<table tabindex="0"><thead><tr><th>Rule</th><th>Value</th></tr></thead><tbody><tr><td>Win</td><td>All target tanks of the level done</td></tr><tr><td>Lose</td><td>Backup full (<code>BACKUP_MAX</code> = 7 slots). The <strong>Out of space!</strong> pop-up first offers Play on (3.11); &quot;No thanks&quot; ends the level on the Level failed screen with a Retry button</td></tr><tr><td>Levels 1-4</td><td>Cannot be lost in practice: L1-2 have no Backup (a wrong tap only makes the fish dart off) and L3-4 have only 6 wrong fish, fewer than the 7 slots. L5 is the first level that can be lost</td></tr><tr><td>Max fish in the tank at once</td><td>40 (<code>FISH_CAP</code>). The pump tube holds decoys back while the tank is full; held target fish still come out first</td></tr><tr><td>Fish at the start of a level</td><td>10 in L1, rising to 40 in L59-60 (<code>startFish</code> in each level file)</td></tr><tr><td>Total levels</td><td>60 (<code>MAX_LV</code>)</td></tr><tr><td>Fish needed per tank</td><td>L1-7: 1 each; from L8 a mix of 1 and 2; from L18 3 appears (<code>tanks</code> in each level file)</td></tr><tr><td>Stars</td><td>Saved per level: at most 3 wrong taps = 3 stars, at most 6 = 2 stars, otherwise 1. There is no stars pop-up; they show in the level list</td></tr></tbody></table>',1)),e("h2",u,[t[3]||(t[3]=s("3.2 Fish ",-1)),a(o,{type:"tip",text:"Live"}),t[4]||(t[4]=s()),t[5]||(t[5]=e("a",{class:"header-anchor",href:"#_3-2-fish","aria-label":'Permalink to "3.2 Fish <Badge type="tip" text="Live" />"'},"​",-1))]),t[39]||(t[39]=n('<ul><li><strong>49 species</strong>, each a 3D model (<code>public/models/fish/&lt;name&gt;/</code>), plus the colour copies used as look-alikes. The shark, the whale and the sea horse are never targets, only wrong fish. A level uses at most 30 species, copies included; the number of species met grows from 4 (L1) to all 49 (L45).</li><li><strong>Look-alikes</strong> (<code>look</code> 0-4 in the level file, from L11 on, see <a href="./levels">Levels</a>): some wrong fish are colour copies of a target species. The colours of a copy are turned in OKLab (the lightness stays what the artist painted) by an angle that gets smaller as levels go up (130 degrees in L1-10 down to 55 in L51-60). Turns that look bad on a species are blocked (<code>HUE_BAD</code>), and a turn that puts pink or purple together with green on one fish (a sickly look) is moved by a few degrees to the nearest good one.</li><li><strong>Size and speed:</strong> every fish is size 1.4 (<code>sizeK</code>) and swims at 85% of its base pace (<code>speedK</code> 0.85) times a further 0.85 (<code>FISH_SLOW</code>), so about 72% of the old base speed. The measured mean speed of a free fish is about 1.2 units a second. Bounty <code>fast</code> fish swim 1.8 times faster.</li><li><strong>Swimming:</strong> fish pick a waypoint, steer to it and use the whole tank (high, low, near the glass). They keep a soft distance from each other (a capped push, never a jump), and nothing passes through anything solid (3.8).</li><li><strong>Per level</strong> the tank holds <code>2 x goal</code> species: <code>goal</code> target species and <code>goal</code> wrong species.</li></ul>',1)),e("h2",g,[t[6]||(t[6]=s("3.3 Obstacles (tapping one counts as a wrong tap) ",-1)),a(o,{type:"tip",text:"Live"}),t[7]||(t[7]=s()),t[8]||(t[8]=e("a",{class:"header-anchor",href:"#_3-3-obstacles-tapping-one-counts-as-a-wrong-tap","aria-label":'Permalink to "3.3 Obstacles (tapping one counts as a wrong tap) <Badge type="tip" text="Live" />"'},"​",-1))]),t[40]||(t[40]=n('<p>An obstacle that is new in a level is shown <strong>alone</strong> in that level (the intro levels L11, L21, L31).</p><table tabindex="0"><thead><tr><th>Obstacle</th><th>From level</th><th>Behaviour</th></tr></thead><tbody><tr><td>Jellyfish</td><td>L8</td><td>Wanders. Tapping sends it to the Backup like a wrong fish</td></tr><tr><td>Octopus</td><td>L11 (alone, as the intro)</td><td>Swims in pushes, sometimes crawls on the sand. Now and then it <strong>sprays ink</strong>: a dark cloud (10 puffs, strongest 85% opaque, about 29% of the water area at its widest, 9 s) that hides what swims behind it. It only sprays in open water (at least 1.1 from the glass and 1.3 above the floor, and the place the jet goes to is also clear). If tapped it goes to the Backup and takes <strong>3 slots</strong></td></tr><tr><td>Clam</td><td>L21 (alone, as the intro)</td><td>Opens and closes and hides a fish inside; the player has to open it. A needed fish in a shut clam is marked by a gold arrow when Hint is used</td></tr><tr><td>Fish swarm</td><td>L31 (alone, as the intro)</td><td>600 grey-silver fish come out of a cave and cover the tank for 18 s, then go back, every 30 s. <strong>Only hides the view</strong>: a tap through the swarm still hits the real fish</td></tr></tbody></table>',2)),e("h2",f,[t[9]||(t[9]=s("3.4 Boosters ",-1)),a(o,{type:"tip",text:"Live"}),t[10]||(t[10]=s()),t[11]||(t[11]=e("a",{class:"header-anchor",href:"#_3-4-boosters","aria-label":'Permalink to "3.4 Boosters <Badge type="tip" text="Live" />"'},"​",-1))]),t[41]||(t[41]=n('<p>Each booster is introduced in its own level: there it can be used once for free, and 3 more are given when that level is won. After that a booster is a count on its button (a &quot;+&quot; when it is 0 opens the Purchase pop-up, 3.11).</p><table tabindex="0"><thead><tr><th>Booster</th><th>From level</th><th>Effect</th></tr></thead><tbody><tr><td>Hint</td><td>L4</td><td>Marks up to 3 needed fish that are not marked yet, with a pulsing gold outline and a bobbing arrow; the mark stays until the fish is caught. The other fish drift away from them. A shell holding a needed fish glows for 3.6 s and shows the arrow. No cooldown. <strong>Nothing is spent</strong> when there is nothing new to mark</td></tr><tr><td>Clear Tank</td><td>L7</td><td>Fills one target tank at once: the fish it still needs fly from the button into it (fish of that kind in the Backup go first)</td></tr><tr><td>Clear Backup</td><td>L9</td><td>Returns the fish in the Backup to the tank: they fly to the open top and drop in with a splash</td></tr></tbody></table><p>A booster that cannot be used right now (Hint with nothing new to mark, Clear Backup with an empty Backup, Clear Tank with nothing to collect) spends nothing, shows a short message (&quot;Already marked!&quot;, &quot;No fish to show&quot;, &quot;Backup is empty&quot;, &quot;Nothing to collect&quot;) and its button shakes sideways for about half a second.</p>',3)),e("h2",m,[t[12]||(t[12]=s("3.5 Random events ",-1)),a(o,{type:"tip",text:"Live"}),t[13]||(t[13]=s()),t[14]||(t[14]=e("a",{class:"header-anchor",href:"#_3-5-random-events","aria-label":'Permalink to "3.5 Random events <Badge type="tip" text="Live" />"'},"​",-1))]),t[42]||(t[42]=n('<p>After <strong>any</strong> event ends (random event, feeding, falling rock, swarm) nothing else starts for <strong>20 s</strong> (<code>EV_COOL</code>), and the same random event never comes twice in a row. Touching a fish makes it leave the event. <strong>Only one big thing happens at a time:</strong> feeding, the pearl game, the falling rock, the swarm and a tube wave wait until the one before has finished. A random event lasts about 7-15 s depending on its kind (measured in the game on 18 Nov 2026: squabble 6.6 s, waltz 7.7 s, swirl 8.1-8.4 s, pearl 11.9 s, conga 14.1-14.7 s; feeding was not timed).</p><table tabindex="0"><thead><tr><th>Event</th><th>From level</th><th>What happens</th></tr></thead><tbody><tr><td>Conga</td><td>L1</td><td>A leader weaves and 6-10 fish follow in a line</td></tr><tr><td>Waltz</td><td>L3</td><td>Two fish chase tails in a small circle</td></tr><tr><td>Swirl</td><td>L6</td><td>A group (up to 14, with a jellyfish or the octopus sometimes) spins into a whirl</td></tr><tr><td>Pearl</td><td>L9</td><td>A pearl drops, the school flees and returns to look, the pearl floats up, a few fish head-butt it, then it pops. At most once per ~80 s</td></tr><tr><td>Squabble</td><td>L12</td><td>Two fish face off, back away, then charge, with dust and a 💢</td></tr><tr><td>Feeding</td><td>L15</td><td>A 3D food bucket drops, shakes, tips and pours 36 pellets on the surface. About 40% of the pellets sink slowly. Every fish picks <strong>one</strong> pellet of its own (the nearest free one), swims up under it with its mouth at the surface and bites it: the pellet is drawn into its mouth and shrinks in 0.2 s; a pellet that sinks out of reach or that nobody can get melts over 0.7 s. Every 24-34 s; the bucket fades as it lifts away</td></tr><tr><td>Falling rock</td><td>L21</td><td>A rock plops into the tank and the school bolts. Every 26-38 s</td></tr></tbody></table><p>The &quot;hide in a cave&quot; event was taken out of the game.</p>',3)),e("h2",b,[t[15]||(t[15]=s("3.6 Pump tube (from L16) ",-1)),a(o,{type:"tip",text:"Live"}),t[16]||(t[16]=s()),t[17]||(t[17]=e("a",{class:"header-anchor",href:"#_3-6-pump-tube-from-l16","aria-label":'Permalink to "3.6 Pump tube (from L16) <Badge type="tip" text="Live" />"'},"​",-1))]),t[43]||(t[43]=e("ul",null,[e("li",null,[s("From L16 part of the fish (targets and decoys) wait in an orange "),e("strong",null,"tube outside the tank"),s(" and are pumped in "),e("strong",null,"in waves"),s(". The tube sits in a corner chosen so no decoration is near it, climbs the outside of the glass, and bends into the tank with a hinged cap.")]),e("li",null,"A wave: the tube shakes and bubbles, the cap opens, fish fly out one by one (squash and stretch). If the tank already holds 40 fish, decoys wait in the tube until the player catches some; fish held back for a target tank are released first. A level has 1 or more waves."),e("li",null,[s("A wave can hold back the "),e("strong",null,"last fish of a target tank"),s(", so the player must wait or find it. If a tank needs a species and none is left in the tank, the tube pumps by itself after ~2.5 s so the game never gets stuck.")]),e("li",null,'The tube is drawn "pre-warped" so it stays straight after the glass lens. It fades when in front of the player or when the camera is close, and becomes clear before a wave. Octopus ink covers it.')],-1)),e("h2",w,[t[18]||(t[18]=s("3.7 Bounty tanks (from L25) ",-1)),a(o,{type:"tip",text:"Live"}),t[19]||(t[19]=s()),t[20]||(t[20]=e("a",{class:"header-anchor",href:"#_3-7-bounty-tanks-from-l25","aria-label":'Permalink to "3.7 Bounty tanks (from L25) <Badge type="tip" text="Live" />"'},"​",-1))]),t[44]||(t[44]=n('<p>Some levels add a x1 tank that asks for one fish, with no species hint, after the first 2 tanks are done.</p><table tabindex="0"><thead><tr><th>Type</th><th>Levels</th><th>Meaning</th></tr></thead><tbody><tr><td><code>tiny</code></td><td>L25, L55</td><td>A very small fish</td></tr><tr><td><code>camo</code></td><td>L35, L55, L60</td><td>Hidden among look-alikes</td></tr><tr><td><code>fast</code></td><td>L45, L60</td><td>Swims very fast</td></tr></tbody></table>',2)),e("h2",c,[t[21]||(t[21]=s("3.8 Collision and layout ",-1)),a(o,{type:"tip",text:"Live"}),t[22]||(t[22]=s()),t[23]||(t[23]=e("a",{class:"header-anchor",href:"#_3-8-collision-and-layout","aria-label":'Permalink to "3.8 Collision and layout <Badge type="tip" text="Live" />"'},"​",-1))]),t[45]||(t[45]=n("<p>Nothing passes through anything, and nothing visible in the tank may overlap anything else.</p><ul><li><strong>Fish and obstacles are pushed out of solid decoration</strong>, the clams and the tube. Every solid piece has a collision box; a piece made of parts (the wreck with its leaning mast) has one box per part. A fish is moved out of a solid by at most 0.045 per frame, so a crowded tank never makes a fish jump. Soft decoration (seaweed, anemones, fans), tiny or flat things and thin parts are ignored. Random spawn points never land inside a solid. A fish leaving the tube has 0.9 s of collision immunity.</li><li><strong>The decoration is laid out again at the start of every level:</strong> each piece keeps its own place around the tank but is turned and moved a little at random; solid pieces never overlap each other, nothing sticks out through the glass (a piece that cannot fit is left out), and soft pieces are moved out of solid ones. The artist&#39;s corals (3 models) are solid and sway gently in the current.</li><li><strong>Clams</strong> are placed where their whole footprint is clear of decoration and of each other.</li><li><strong>Paused</strong> (a pop-up is open, or the window lost focus): nothing moves.</li><li><strong>Checks</strong> in the game (<code>window.__qa</code>, see the QA page): <code>decorFit</code> (decor against decor and the glass), <code>fishClip</code>, <code>overlapAudit</code>, <code>jitter</code> (smoothness of the swimming).</li></ul>",2)),e("h2",k,[t[24]||(t[24]=s("3.9 Tutorial and introductions ",-1)),a(o,{type:"tip",text:"Live"}),t[25]||(t[25]=s()),t[26]||(t[26]=e("a",{class:"header-anchor",href:"#_3-9-tutorial-and-introductions","aria-label":'Permalink to "3.9 Tutorial and introductions <Badge type="tip" text="Live" />"'},"​",-1))]),t[46]||(t[46]=e("ul",null,[e("li",null,"No long tutorial. L1: a short goal pop-up, a hand pointing at a fish, then camera hints (drag to rotate, then zoom, then moving the view up and down with two fingers)."),e("li",null,[s("New features are introduced by "),e("strong",null,"dimming the screen and lighting the real button"),s(" with one short line: Backup (L3), Hint (L4), Clear Tank (L7), Clear Backup (L9), Octopus (L11), Pipe (L16), Clam (L21), Swarm (L31). The pop-ups wait until the UI and the lids of the target tanks have finished.")]),e("li",null,[e("strong",null,"No"),s(" dedicated tutorial for feeding.")])],-1)),e("h2",y,[t[27]||(t[27]=s("3.10 Themes and tank shapes ",-1)),a(o,{type:"tip",text:"Live"}),t[28]||(t[28]=s()),t[29]||(t[29]=e("a",{class:"header-anchor",href:"#_3-10-themes-and-tank-shapes","aria-label":'Permalink to "3.10 Themes and tank shapes <Badge type="tip" text="Live" />"'},"​",-1))]),t[47]||(t[47]=e("ul",null,[e("li",null,[s("The hall changes "),e("strong",null,"every 10 levels"),s(" between 6 looks (water colour, light, hall): in this order Aquarium hall (L1-10), Sunset reef (L11-20), Kelp forest (L21-30), Atlantis (L31-40), Lagoon (L41-50), Deep sea (L51-60).")]),e("li",null,"There are 5 decoration sets: reef (L1-10 and L41-50), ruins (L11-20), kelp forest (L21-30), Atlantis (L31-40) and shipwreck (L51-60). The tank shape changes every 10 levels too: cylinder, bowl, rounded box, hexagon, flower, heart.")],-1)),t[48]||(t[48]=e("p",null,[s("See "),e("a",{href:"./levels"},"Levels"),s(" for the per-level table.")],-1)),e("h2",v,[t[30]||(t[30]=s("3.11 Coins, boosters and ads ",-1)),a(o,{type:"warning",text:"Prototype: ads not connected"}),t[31]||(t[31]=s()),t[32]||(t[32]=e("a",{class:"header-anchor",href:"#_3-11-coins-boosters-and-ads","aria-label":'Permalink to "3.11 Coins, boosters and ads <Badge type="warning" text="Prototype: ads not connected" />"'},"​",-1))]),t[49]||(t[49]=n("<ul><li><strong>Coins:</strong> start with 900. A win pays 30 (Easy, Medium), 60 (Hard) or 90 (Very Hard). The WELL DONE screen lets the player take it, or watch an ad for x2.</li><li><strong>Booster prices (3 per pack):</strong> Hint 300, Clear Backup 900, Clear Tank 1500. A purchase by ad gives 1.</li><li><strong>Play on</strong> when the Backup is full: clears the Backup (the fish jump back into the tank, no extra slot). The player&#39;s <strong>first Play on is FREE</strong>: the pop-up has one button, &quot;FREE&quot;, until that free one has been used. After that, with coins (900) there is no limit per level; by ad, at most <strong>5 a day</strong>.</li><li><strong>Rewarded ads</strong> (x2 reward, booster by ad, Play on by ad): each kind is capped at <strong>5 a day</strong>, and each booster has its own 5. When a kind is used up its ad button is removed and the pop-up shows the coin button alone, in the middle. In the prototype the ad buttons grant the reward at once; no ad network is attached.</li><li><strong>Pop-ups</strong> keep their buttons as they were when a button was pressed until they close (so the free Play on does not turn into the two-button pop-up for a moment).</li><li><strong>Interstitial ads:</strong> the first one appears at <strong>Level 15</strong>, and two interstitials are at least <strong>120 seconds</strong> apart. Not built yet: this is the agreed design. A rewarded ad does not reset or count towards the 120 s unless decided otherwise (open question for the full GDD).</li></ul>",1)),e("h2",L,[t[33]||(t[33]=s("3.12 The win sequence ",-1)),a(o,{type:"tip",text:"Live"}),t[34]||(t[34]=s()),t[35]||(t[35]=e("a",{class:"header-anchor",href:"#_3-12-the-win-sequence","aria-label":'Permalink to "3.12 The win sequence <Badge type="tip" text="Live" />"'},"​",-1))]),t[50]||(t[50]=e("p",null,'When the last target tank is done the UI fades out, the camera pulls back and the fish that are left swirl up out of the tank, circle in a bubble and fall back into the water; the words LEVEL COMPLETE appear. From level 2 a grey breathing line "TAP TO FAST FORWARD" shows under the tank; after a tap it reads FAST FORWARD with three triangles until the WELL DONE screen has built up (it slides under the two coin buttons when that screen opens). Then WELL DONE shows the coins to take (with x2 by ad), the progress to the next unlocked feature and, when a feature is earned, UNLOCKED!. The next level opens behind a curtain.',-1))])}const E=i(h,[["render",T]]);export{B as __pageData,E as default};
